sbi_platform_pmp_set(sbi_platform_ptr(scratch), SBI_SMEPMP_RESV_ENTRY,
                     SBI_DOMAIN_MEMREGION_SHARED_SURW_MRW,
                     pmp_flags, base, order);
pmp_set(SBI_SMEPMP_RESV_ENTRY, pmp_flags, base, order);

return SBI_OK;

/* Reconfigure PMP settings for the new domain */
sbi_hart_protection_unconfigure(scratch);
sbi_hart_protection_configure(scratch);

pmp_set(PMP_FREE_A_START + PMP_FREE_A_COUNT - 1, 0, 0,
        log2roundup(EIC770X_MEMPORT_BASE));

for (unsigned int i = 0; i < PMP_FREE_A_COUNT - 1; i++)
        pmp_disable(i + PMP_FREE_A_START);

for (unsigned int i = 0; i < PMP_FREE_B_COUNT; i++)
        pmp_disable(i + PMP_FREE_B_START);

for(; pmp_idx < pmp_count; pmp_idx++)
        pmp_disable(pmp_idx);

sbi_hart_pmp_fence();
return 0;

for(; pmp_idx < pmp_count; pmp_idx++)
        pmp_disable(pmp_idx);

sbi_hart_pmp_fence();
return 0;

rc = sbi_hart_protection_configure(scratch);
if (rc) {
        sbi_printf("%s: hart isolation configure failed (error %d)\n",
                   __func__, rc);
        sbi_hart_hang();
}

rc = sbi_hart_protection_configure(scratch);
if (rc)
        sbi_hart_hang();

sbi_hsm_hart_start_finish(scratch, hartid);

rc = sbi_hart_protection_configure(scratch);
if (rc)
        sbi_hart_hang();

